import{_ as a,o as s,c as i,a2 as o}from"./chunks/framework.DCVnL8g5.js";const u=JSON.parse('{"title":"Despliegue","description":"","frontmatter":{},"headers":[],"relativePath":"ia/vllm/05-despliegue.md","filePath":"ia/vllm/05-despliegue.md","lastUpdated":1789040978000,"isDraft":false}'),n={name:"ia/vllm/05-despliegue.md"};function l(t,e,r,d,p,c){return s(),i("div",null,[...e[0]||(e[0]=[o(`<h1 id="despliegue" tabindex="-1">Despliegue <a class="header-anchor" href="#despliegue" aria-label="Permalink to &quot;Despliegue&quot;">​</a></h1><p>vLLM no se “despliega” como una app web cualquiera: levantas un <strong>servidor de inferencia</strong> que carga un modelo en GPU y expone una API HTTP <strong>compatible con OpenAI</strong>. Los clientes (tu backend, un playground, LangChain) apuntan a esa URL en lugar de a <code>api.openai.com</code>.</p><p>El detalle de los endpoints vive en <a href="./02-servidor-openai-compatible">Servidor OpenAI compatible</a>. Este capítulo cubre cómo <strong>arrancar</strong>, dimensionar GPU y publicar el servicio.</p><p>Documentación oficial: <a href="https://docs.vllm.ai/en/latest/cli/serve/" target="_blank" rel="noreferrer">vllm serve</a>, <a href="https://docs.vllm.ai/en/stable/serving/parallelism_scaling/" target="_blank" rel="noreferrer">paralelismo</a>, <a href="https://docs.vllm.ai/en/latest/deployment/docker.html" target="_blank" rel="noreferrer">Docker</a>.</p><h2 id="que-estas-sirviendo" tabindex="-1">Qué estás sirviendo <a class="header-anchor" href="#que-estas-sirviendo" aria-label="Permalink to &quot;Qué estás sirviendo&quot;">​</a></h2><ul><li><strong>Motor:</strong> el modelo (pesos + KV cache) reside en VRAM. Si no cabe, hay que recortar contexto, cuantizar o partir el modelo entre GPUs.</li><li><strong>Frontend HTTP:</strong> por defecto escucha en el puerto <strong>8000</strong> y habla JSON al estilo OpenAI (<code>/v1/chat/completions</code>, <code>/v1/completions</code>, <code>/v1/models</code>).</li><li><strong>Nombre del modelo en la API:</strong> coincide con <code>--model</code> salvo que pongas <code>--served-model-name</code>.</li></ul><p>La CLI actual es <code>vllm serve</code>, no un script genérico de Python. El valor por defecto de <code>--model</code> en la CLI es un modelo pequeño de Qwen; en producción eliges el que necesites y que quepa en tus GPUs.</p><h2 id="arranque-minimo" tabindex="-1">Arranque mínimo <a class="header-anchor" href="#arranque-minimo" aria-label="Permalink to &quot;Arranque mínimo&quot;">​</a></h2><p>Con vLLM instalado en un entorno con GPU NVIDIA y drivers CUDA:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">vllm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> serve</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> Qwen/Qwen3-0.6B</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --host</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 0.0.0.0</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --port</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 8000</span></span></code></pre></div><p>Comprueba que el proceso está vivo:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -s</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> http://127.0.0.1:8000/v1/models</span></span></code></pre></div><p>Petición de chat (el campo <code>model</code> debe ser el nombre servido):</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> http://127.0.0.1:8000/v1/chat/completions</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  -H</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;Content-Type: application/json&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  -d</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;{&quot;model&quot;:&quot;Qwen/Qwen3-0.6B&quot;,&quot;messages&quot;:[{&quot;role&quot;:&quot;user&quot;,&quot;content&quot;:&quot;Di hola en una frase.&quot;}]}&#39;</span></span></code></pre></div><p>En un servidor expuesto a red, añade autenticación. <code>--api-key</code> obliga a enviar esa clave en la cabecera de las peticiones.</p><h2 id="gpu-y-memoria" tabindex="-1">GPU y memoria <a class="header-anchor" href="#gpu-y-memoria" aria-label="Permalink to &quot;GPU y memoria&quot;">​</a></h2><p>La VRAM se reparte sobre todo entre <strong>pesos del modelo</strong> y <strong>KV cache</strong> (crece con el contexto y con el número de peticiones concurrentes).</p><p>Parámetros relevantes de <code>vllm serve</code> (no inventes flags: están en la CLI oficial):</p><table tabindex="0"><thead><tr><th>Flag</th><th>Qué controla</th></tr></thead><tbody><tr><td><code>--gpu-memory-utilization</code></td><td>Fracción de VRAM que vLLM puede usar en <strong>esta</strong> instancia. Por defecto <strong>0.92</strong>. Bájalo (por ejemplo <code>0.5</code>) si compartes la GPU o ves OOM.</td></tr><tr><td><code>--max-model-len</code></td><td>Longitud máxima de prompt + salida. Si no cabe el contexto completo del modelo, fíjalo a un valor menor para dejar memoria al batch.</td></tr><tr><td><code>--dtype</code></td><td>Tipo de los pesos cuando aplica (<code>auto</code>, <code>float16</code>, <code>bfloat16</code>, …).</td></tr><tr><td><code>--tensor-parallel-size</code> / <code>-tp</code></td><td>Número de GPUs entre las que se parte el modelo (tensor parallelism). Por defecto <code>1</code>.</td></tr></tbody></table><p>Ejemplo en una máquina con 2 GPUs, dejando margen de VRAM:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">vllm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> serve</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> Qwen/Qwen3-0.6B</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --tensor-parallel-size</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 2</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --gpu-memory-utilization</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 0.90</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --max-model-len</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 4096</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --port</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 8000</span></span></code></pre></div><p>Tensor parallelism tiene sentido cuando el modelo <strong>no cabe en una GPU</strong> o quieres más KV cache. En un solo nodo, vLLM usa multiprocessing; entre nodos hace falta el backend distribuido documentado (Ray) y <code>--pipeline-parallel-size</code> si partes por pipeline. Empieza por TP = número de GPUs del nodo.</p><p>Si la GPU se queda sin memoria al arrancar o al subir la concurrencia: baja <code>--gpu-memory-utilization</code>, reduce <code>--max-model-len</code>, usa un modelo más pequeño o aumenta <code>-tp</code>.</p><h2 id="docker" tabindex="-1">Docker <a class="header-anchor" href="#docker" aria-label="Permalink to &quot;Docker&quot;">​</a></h2><p>Imagen oficial: <code>vllm/vllm-openai</code>. El entrypoint ejecuta el servidor; el argumento posicional es el modelo. <code>--ipc=host</code> evita quedarse corto de memoria compartida, importante con varias GPUs.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --rm</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --gpus</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> all</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  -v</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ~/.cache/huggingface:/root/.cache/huggingface</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  -p</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> 8000:8000</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --ipc=host</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">  vllm/vllm-openai:latest</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">  Qwen/Qwen3-0.6B</span></span></code></pre></div><p>Montar la caché de Hugging Face evita volver a descargar pesos. La imagen corre como root por defecto; la documentación oficial describe el usuario no root <code>vllm</code> (UID 2000) si lo necesitas.</p><p>No publiques el puerto 8000 a Internet sin <code>--api-key</code>, TLS (terminación en un proxy) y control de red. vLLM es un servicio de inferencia, no un API gateway.</p><h2 id="errores-habituales" tabindex="-1">Errores habituales <a class="header-anchor" href="#errores-habituales" aria-label="Permalink to &quot;Errores habituales&quot;">​</a></h2><ul><li>Tratar el despliegue como “un script que lee ficheros”. Si no hay <code>vllm serve</code> (o la imagen <code>vllm/vllm-openai</code>) y una GPU visible, no estás sirviendo el modelo.</li><li>Pedir un <code>model</code> en el JSON distinto al nombre servido. <code>/v1/models</code> lista el identificador correcto.</li><li>Dejar <code>--gpu-memory-utilization</code> en 0.92 junto a otros procesos en la misma GPU. La fracción es <strong>por instancia</strong>.</li><li>Usar <code>-tp</code> mayor que el número de GPUs visibles.</li><li>Exponer el puerto sin clave ni red privada.</li></ul><h2 id="buenas-practicas" tabindex="-1">Buenas prácticas <a class="header-anchor" href="#buenas-practicas" aria-label="Permalink to &quot;Buenas prácticas&quot;">​</a></h2><ul><li>Fija la <strong>versión de la imagen</strong> o del paquete vLLM; <code>latest</code> cambia el comportamiento.</li><li>Fija el <strong>modelo</strong> (id de Hugging Face o ruta local) y, si aplica, el revision.</li><li>Mide latencia y throughput con concurrencia real antes de subir contexto o batch.</li><li>Coloca un proxy (Nginx, Traefik, ingress) delante para TLS, timeouts y límites de cuerpo.</li><li>El siguiente capítulo cubre métricas; no operes en producción a ciegas.</li></ul><h2 id="ejercicio" tabindex="-1">Ejercicio <a class="header-anchor" href="#ejercicio" aria-label="Permalink to &quot;Ejercicio&quot;">​</a></h2><ol><li>Arranca <code>vllm serve</code> con un modelo que quepa en tu GPU (o en un entorno cloud con GPU).</li><li>Lista modelos con <code>GET /v1/models</code> y haz un <code>chat/completions</code>.</li><li>Si tienes dos GPUs, repite con <code>--tensor-parallel-size 2</code> y compara si el modelo grande ahora carga.</li><li>Provoca un OOM a propósito (contexto enorme o utilización alta) y corrígelo bajando <code>--max-model-len</code> o <code>--gpu-memory-utilization</code>.</li></ol><h2 id="siguiente-paso" tabindex="-1">Siguiente paso <a class="header-anchor" href="#siguiente-paso" aria-label="Permalink to &quot;Siguiente paso&quot;">​</a></h2><p>Continúa con <a href="./06-observabilidad">Observabilidad</a>.</p>`,36)])])}const k=a(n,[["render",l]]);export{u as __pageData,k as default};
